351	static void
352	calc_stat(void)
353	{
354	  int16_t *p = &rx_buffer[0];
355	  int16_t min0 = 0, min1 = 0;
356	  int16_t max0 = 0, max1 = 0;
357	  int32_t count = AUDIO_BUFFER_LEN;
358	  int i;
359	  float accx0 = 0, accx1 = 0;
360	  for (i = 0; i < AUDIO_BUFFER_LEN*2; i += 2) {
361	    if (min0 > p[i]) min0 = p[i];
362	    if (min1 > p[i+1]) min1 = p[i+1];
363	    if (max0 < p[i]) max0 = p[i];
364	    if (max1 < p[i+1]) max1 = p[i+1];
365	    float x0 = p[i];
366	    float x1 = p[i+1];
367	    accx0 += x0 * x0;
368	    accx1 += x1 * x1;
369	  }
370	  stat.rms[0] = sqrtf(accx0 / count);
371	  stat.rms[1] = sqrtf(accx1 / count);
372	  stat.min[0] = min0;
373	  stat.min[1] = min1;
374	  stat.max[0] = max0;
375	  stat.max[1] = max1;
376	}  
