611	    } else if (strncmp(cmd, "hy", 2) == 0 && argc == 2) {
612	      config.agc.gain_hysteresis = atoi(argv[1]);
613	      tlv320aic3204_agc_config(&config.agc);
614	    } else if (strncmp(cmd, "at", 2) == 0 && argc >= 2) {
615	      config.agc.attack = atoi(argv[1]);
616	      if (argc >= 3)
617	        config.agc.attack_scale = atoi(argv[2]);
618	      tlv320aic3204_agc_config(&config.agc);
619	    } else if (strncmp(cmd, "de", 2) == 0 && argc >= 2) {
620	      config.agc.decay = atoi(argv[1]);
621	      if (argc >= 3)
622	        config.agc.decay_scale = atoi(argv[2]);
623	      tlv320aic3204_agc_config(&config.agc);
624	    } else if (strncmp(cmd, "max", 3) == 0 && argc >= 2) {
625	      config.agc.maximum_gain = atoi(argv[1]);
626	      tlv320aic3204_agc_config(&config.agc);
627	    }
628	}
