630	void set_agc_mode(int mode)
631	{
632	  if (mode == AGC_MANUAL) {
633	    tlv320aic3204_agc_config(NULL);
634	    uistat.agcmode = mode;
635	    disp_update();
636	    return;
637	  }
638	  switch (mode) {
639	  case AGC_FAST:
640	    config.agc.decay = 0;
641	    config.agc.decay_scale = 0;
642	    break;
643	  case AGC_MID:
644	    config.agc.decay = 7;
645	    config.agc.decay_scale = 0;
646	    break;
647	  case AGC_SLOW:
648	    config.agc.decay = 31;
649	    config.agc.decay_scale = 4;
650	    break;
651	  }
652	  tlv320aic3204_agc_config(&config.agc);
653	  uistat.agcmode = mode;
654	  disp_update();
655	}
