943	/*
944	 * Application entry point.
945	 */
946	int __attribute__((noreturn)) main(void)
947	{
948	  /*
949	   * System initializations.
950	   * - HAL initialization, this also initializes the configured device drivers
951	   *   and performs the board-specific initializations.
952	   * - Kernel initialization, the main() function becomes a thread and the
953	   *   RTOS is active.
954	   */
955	  halInit();
956	  chSysInit();
957	
958	  /* restore config */
959	  config_recall();
960	
961	  if (config.button_polarity != 0) {
962	    // pullup for revision 1 board
963	    palSetGroupMode(GPIOA, 1, 0, PAL_MODE_INPUT_PULLUP);
964	    palSetGroupMode(GPIOB, 6, 0, PAL_MODE_INPUT_PULLUP);
965	  }
966	  
967	  // copy uistat from uistat
968	  uistat = config.uistat;
969	
970	  /*
971	   * Starting DAC1 driver, setting up the output pin as analog as suggested
972	   * by the Reference Manual.
973	   */
974	  dac1cfg1.init = config.dac_value;
975	  dacStart(&DACD1, &dac1cfg1);
976	
977	  /*
978	   * Activates the ADC1 driver and the temperature sensor.
979	   */
980	  adcStart(&ADCD1, NULL);
981	  adcSTM32EnableTS(&ADCD1);
982	  adcSTM32EnableVBAT(&ADCD1);
983	  adcSTM32EnableVREF(&ADCD1);
984	
985	  
986	  i2cStart(&I2CD1, &i2ccfg);
987	  /*
988	   * Initializes a serial-over-USB CDC driver.
989	   */
990	  sduObjectInit(&SDU1);
991	  sduStart(&SDU1, &serusbcfg);
992	
993	  /*
994	   * Activates the USB driver and then the USB bus pull-up on D+.
995	   * Note, a delay is inserted in order to not have to disconnect the cable
996	   * after a reset.
997	   */
998	  usbDisconnectBus(serusbcfg.usbp);
